  mvc.perform(post(budget).header("Authorization",bearer(p.token)).header("Idempotency-Key","budget-coin-1").contentType(MediaType.APPLICATION_JSON).content(coinRule)).andExpect(status().isCreated()).andExpect(jsonPath("$.data.id").exists());
  UUID first=completion(p,child,ct,"budget-task-a");review(p,first,"budget-review-a","{\"approved\":true,\"xpReward\":0,\"coinReward\":1,\"moneyReward\":8.00,\"reviewNote\":\"按家庭预算结算\"}",200);
